    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address a) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint testBalBefore = address(this).balance;
        uint cBalBefore = address(c).balance;
        uint recordedA = c.balances(a); if (__ESBMC_reverted()) return;
        uint recordedSelf = c.balances(address(this)); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && recordedA == 0 && c.balances(a) == 0 && recordedSelf == 0 && c.balances(address(this)) == 0 && address(c).balance == cBalBefore && address(this).balance == testBalBefore);
    }
    receive() external payable {}
}

