// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address a) internal {
        vm.deal(address(c), VALUE_CAP);
        uint testBalBefore = address(this).balance;
        uint cBalBefore = address(c).balance;
        uint256 recordedA;
        try c.balances(a) returns (uint256 __r) { recordedA = __r; } catch { return; }
        uint256 recordedSelf;
        try c.balances(address(this)) returns (uint256 __r) { recordedSelf = __r; } catch { return; }
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && recordedA == 0 && c.balances(a) == 0 && recordedSelf == 0 && c.balances(address(this)) == 0 && address(c).balance == cBalBefore && address(this).balance == testBalBefore);
    }

    function testFuzz_run(address a) public {
        vm.assume(a.code.length == 0 && uint160(a) > 0xffff && a != address(this) && a != address(c) && a != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && a != 0x000000000000000000636F6e736F6c652e6c6f67 && a != 0x4e59b44847b379578588920cA78FbF26c0B4956C && a != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(a);
    }

    receive() external payable {}
}
